[meta]
name = The Verdant Hollow
ambient = 0.24 0.31 0.21
fog = 0.05 0.11 0.07
fog_range = 3 22
torch = 8 0.7 0.78 0.55
start = 15 27 -90
default = ,
edge_top = 6
edge_tex = vine_wall

[legend]
# = wall tex=vine_wall top=6 cap=canopy
B = wall tex=bark top=8 cap=canopy
, = floor tex=jungle_floor h=0 side=bark
. = floor tex=leaf_litter h=0 ceil=4.6 ceil_tex=canopy side=bark
r = floor tex=leaf_litter h=0.4 ceil=4.6 ceil_tex=canopy side=bark
R = floor tex=leaf_litter h=0.8 ceil=4.6 ceil_tex=canopy side=bark
m = floor tex=jungle_floor h=0.4 side=bark
M = floor tex=jungle_floor h=0.8 side=bark
^ = floor tex=leaf_litter h=1.2 side=bark
- = floor tex=mud h=-0.2 side=mud slow=0.65
= = floor tex=wood_plank h=0.05 side=wood_plank
~ = water tex=bog h=-0.5 side=mud
w = floor tex=rapids h=-0.3 side=mud flow=0,0.8 slow=0.8
* = floor tex=thorns h=0 side=mud hurt=5
% = floor tex=thorns h=0.4 side=bark hurt=5
A = wall tex=cliff_rock top=9 cap=cliff_rock
C = wall tex=log_wall top=6.6 cap=roof
Q = wall tex=log_wall top=4.8 cap=roof
g = floor tex=jungle_floor h=3.2 side=cliff_rock
_ = floor tex=ravine h=-5 side=cliff_rock chasm
1 = floor tex=cliff_rock h=0.8 side=cliff_rock
2 = floor tex=cliff_rock h=1.2 side=cliff_rock
3 = floor tex=cliff_rock h=1.6 side=cliff_rock
4 = floor tex=cliff_rock h=2.0 side=cliff_rock
5 = floor tex=cliff_rock h=2.4 side=cliff_rock
6 = floor tex=cliff_rock h=2.8 side=cliff_rock
i = floor tex=wood_plank h=3.2 ceil=5.8 ceil_tex=wood_plank side=log_wall
e = floor tex=mud h=0.8 ceil=5.8 ceil_tex=wood_plank side=log_wall
u = floor tex=wood_plank h=1.6 ceil=4.2 ceil_tex=wood_plank side=log_wall
+ = floor tex=wood_plank h=0.8 side=wood_plank
& = floor tex=wood_plank h=1.2 side=wood_plank

